from fractions import Fraction

M = 2025
N_max = 2024

def calculate_D_n(M, n):
    # T_1,n = M^n / [(M+1)...(M+n)]
    T1_n = 1
    for k in range(1, n + 1):
        T1_n = T1_n * (Fraction(M, M + k))

    # T_2,n = [(M-1)...(M-n)] / M^n
    T2_n = 1
    for k in range(1, n + 1):
        T2_n = T2_n * (Fraction(M - k, M))

    return T1_n - T2_n

D_terms = {}
for n in range(1, 6):
    D_terms[n] = calculate_D_n(M, n)

print("First 5 terms of D_n (as fractions):")
for n in range(1, 6):
    print(f"D_{n}: {D_terms[n]}")

# Calculate the decimal approximations for rate analysis
print("\nDecimal approximations for D_n:")
for n in range(1, 6):
    print(f"D_{n} approx: {float(D_terms[n])}")
